import * as T from 'three';
const KEY='greyman-harvesting-v1';
export function trackResources(world){
 world.resources=[];let current=null;
 for(const type of ['tree','rock']){const original=world[type];world[type]=function(x,y,z,size=1,...rest){const parent=current;const r={id:`${type}:${x.toFixed(3)}:${y.toFixed(3)}:${z.toFixed(3)}`,type,x,y,z,size,radius:type==='tree'?.5*size:size*.7,maxHp:type==='tree'?Math.max(3,Math.ceil(size*4)):Math.max(3,Math.ceil(size*2)),parts:[],colliders:[]};r.hp=r.maxHp;world.resources.push(r);current=r;try{return original.call(this,x,y,z,size,...rest)}finally{current=parent}};}
 const box=world.b;world.b=function(...args){const result=box.apply(this,args);if(current){const [layer,,,,,,,color]=args,geo=args[9]||'box',key=layer+'|'+geo+'|'+color,batch=this.batches.get(key);current.parts.push({name:layer+'_'+geo+'_'+color.toString(16),index:batch.items.length-1,matrix:batch.items[batch.items.length-1].clone()});}return result};
 const collider=world.collider;world.collider=function(...args){collider.apply(this,args);if(current){const c=this.colliders[this.colliders.length-1];c.resourceId=current.id;current.colliders.push({c,index:this.colliders.length-1})}};
 return world;
}
export function createHarvesting({world,character,greyMan,scene,isWalking,toast}){
 const resources=world.resources,byName=new Map();world.root.traverse(n=>{if(n.isInstancedMesh)byName.set(n.name,n)});for(const r of resources)for(const p of r.parts)p.mesh=byName.get(p.name);
 let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}const inventory={wood:Math.max(0,Number(saved.wood)||0),stone:Math.max(0,Number(saved.stone)||0)};
 const zero=new T.Matrix4().makeScale(0,0,0),matrix=new T.Matrix4(),a=new T.Matrix4(),b=new T.Matrix4(),rotation=new T.Matrix4();let target=null,pending=null,cooldown=0,damage=1;const effects=[],motions=[];
 const hud=document.createElement('div');hud.id='harvestHud';hud.innerHTML='<div class="inventory"><span>Madera <b id="woodCount">0</b></span><span>Piedra <b id="stoneCount">0</b></span></div><div id="harvestTarget"></div>';document.body.append(hud);const targetLabel=document.getElementById('harvestTarget');
 const ring=new T.Mesh(new T.RingGeometry(.62,.7,28),new T.MeshBasicMaterial({color:0xf2d899,side:T.DoubleSide,transparent:true,opacity:.9,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.visible=false;scene.add(ring);
 const forearm=character.getObjectByName('ForearmR'),tool=new T.Group();tool.name='Herramienta_recoleccion';tool.position.set(0,-.17,.13);forearm.add(tool);const handle=new T.Mesh(new T.BoxGeometry(.06,.54,.06),new T.MeshToonMaterial({color:0x906548}));handle.position.y=-.11;tool.add(handle);const metal=new T.MeshToonMaterial({color:0xc2cbd0});const axe=new T.Mesh(new T.BoxGeometry(.27,.2,.075),metal);axe.position.set(.09,-.35,0);tool.add(axe);const pick=new T.Group();const bar=new T.Mesh(new T.BoxGeometry(.48,.065,.065),metal);pick.add(bar);for(const sign of [-1,1]){const tip=new T.Mesh(new T.BoxGeometry(.06,.15,.055),metal);tip.position.set(sign*.21,-.05,0);tip.rotation.z=sign*.3;pick.add(tip)}pick.position.y=-.35;tool.add(pick);tool.visible=false;
 function changeParts(r,transform){const touched=new Set();for(const p of r.parts){if(!p.mesh)continue;p.mesh.setMatrixAt(p.index,transform?matrix.multiplyMatrices(transform,p.matrix):zero);touched.add(p.mesh)}for(const mesh of touched)mesh.instanceMatrix.needsUpdate=true;}
 function disableColliders(r){const guide=byName.get('Colliders_AABB');for(const {c,index}of r.colliders){c.removed=true;if(guide)guide.setMatrixAt(index,zero)}if(guide)guide.instanceMatrix.needsUpdate=true;}
 function stump(r){if(r.type!=='tree')return;const m=new T.Mesh(new T.CylinderGeometry(.31*r.size,.4*r.size,.15,8),new T.MeshToonMaterial({color:0x805b40}));m.position.set(r.x,r.y+.065,r.z);m.name='Tocon_'+r.id;world.layers.Vegetacion.add(m);r.stump=m}
 function persist(){const state={wood:inventory.wood,stone:inventory.stone,resources:{}};for(const r of resources)if(r.hp!==r.maxHp)state.resources[r.id]=r.hp;try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}document.getElementById('woodCount').textContent=inventory.wood;document.getElementById('stoneCount').textContent=inventory.stone;}
 for(const r of resources){if(Object.hasOwn(saved.resources||{},r.id)){r.hp=T.MathUtils.clamp(Number(saved.resources[r.id])||0,0,r.maxHp);if(r.hp===0){changeParts(r,null);disableColliders(r);stump(r)}}}persist();
 function reachable(r){if(r.hp<=0||Math.abs(character.position.y-r.y)>1.5)return false;const dx=r.x-character.position.x,dz=r.z-character.position.z,dist=Math.hypot(dx,dz);if(dist>1.6+r.radius)return false;
  // Intervening walls and other resources block the strike; ignore the target's own collider.
  for(const c of world.colliders){if(c.removed||c.resourceId===r.id||character.position.y+.85<c.y-c.h/2||character.position.y+.85>c.y+c.h/2)continue;const t=T.MathUtils.clamp(((c.x-character.position.x)*dx+(c.z-character.position.z)*dz)/(dist*dist||1),0,1);if(t>.06&&t<.92&&Math.abs(character.position.x+dx*t-c.x)<c.w/2&&Math.abs(character.position.z+dz*t-c.z)<c.d/2)return false;}return true;}
 function findTarget(){let found=null,best=Infinity;for(const r of resources){const d=Math.hypot(r.x-character.position.x,r.z-character.position.z)-r.radius;if(d<best&&d<=1.6&&reachable(r)){found=r;best=d}}return found;}
 function particles(r,count){const geo=new T.BoxGeometry(.12,.12,.12);for(let i=0;i<count;i++){const m=new T.Mesh(geo,new T.MeshToonMaterial({color:r.type==='tree'?(i%3?0xb68b57:0x618448):0xb1b6b0}));m.position.set(r.x,r.y+.6,r.z);scene.add(m);effects.push({m,life:.7+Math.random()*.4,v:new T.Vector3((Math.random()-.5)*3,1.5+Math.random()*2,(Math.random()-.5)*3),ground:r.y,geo});}}
 function strike(){if(!isWalking()||cooldown>0)return;const r=findTarget();if(!r){toast('Acércate a un árbol o una roca para talar o picar.');return}if(api.canStrike&&!api.canStrike(r))return;target=r;character.rotation.y=Math.atan2(r.x-character.position.x,r.z-character.position.z);tool.visible=true;axe.visible=r.type==='tree';pick.visible=!axe.visible;greyMan.trigger();cooldown=.7;pending={r,time:.32};}
 function hit(r){if(!isWalking()||!reachable(r))return;r.hp=Math.max(0,r.hp-(api.damageFor?api.damageFor(r):api.damage));particles(r,r.hp?5:16);if(r.hp===0){disableColliders(r);const amount=r.type==='tree'?Math.max(2,Math.round(r.size*4)):Math.max(2,Math.round(r.size*2));inventory[r.type==='tree'?'wood':'stone']+=amount;toast(`+${amount} ${r.type==='tree'?'madera':'piedra'}`);if(r.type==='tree'){motions.push({r,time:0,fall:true,angle:character.rotation.y});stump(r)}else{changeParts(r,null);}window.dispatchEvent(new Event('world-physics-changed'));}else motions.push({r,time:0,fall:false});window.dispatchEvent(new CustomEvent('life:activity',{detail:{skill:r.type==='tree'?'logging':'mining',xp:r.hp===0?(r.type==='tree'?12:15):2,count:r.hp===0?1:0,finished:r.hp===0,resource:r}}));persist();}
 function update(dt){cooldown=Math.max(0,cooldown-dt);if(pending){pending.time-=dt;if(pending.time<=0){const r=pending.r;pending=null;hit(r)}}hud.hidden=!isWalking();target=isWalking()?findTarget():null;ring.visible=!!target;if(target){ring.position.set(target.x,target.y+.08,target.z);ring.scale.setScalar(Math.max(1,target.radius));targetLabel.textContent=`${target.type==='tree'?'E · Talar árbol':'E · Picar roca'} — ${target.hp}/${target.maxHp}`;}else targetLabel.textContent='Acércate a un árbol o una roca · E para golpear';if(cooldown===0){tool.visible=!!target;axe.visible=target?.type==='tree';pick.visible=target?.type==='rock';}
  for(let i=motions.length-1;i>=0;i--){const m=motions[i];m.time+=dt;if(m.fall){const t=Math.min(1,m.time/.9);a.makeTranslation(m.r.x,m.r.y,m.r.z);rotation.makeRotationAxis(new T.Vector3(Math.cos(m.angle),0,-Math.sin(m.angle)),t*t*1.45);b.makeTranslation(-m.r.x,-m.r.y,-m.r.z);a.multiply(rotation).multiply(b);changeParts(m.r,a);if(t===1){changeParts(m.r,null);motions.splice(i,1)}}else{if(m.r.hp===0){motions.splice(i,1);continue}a.makeTranslation(Math.sin(m.time*50)*.045*Math.max(0,1-m.time/.2),0,0);changeParts(m.r,a);if(m.time>=.2){changeParts(m.r,new T.Matrix4());motions.splice(i,1)}}}
  for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;e.v.y-=7*dt;e.m.position.addScaledVector(e.v,dt);e.m.position.y=Math.max(e.ground+.06,e.m.position.y);e.m.rotation.x+=dt*4;e.m.scale.setScalar(Math.min(1,e.life*3));if(e.life<=0){scene.remove(e.m);e.m.material.dispose();effects.splice(i,1);if(!effects.some(p=>p.geo===e.geo))e.geo.dispose();}}
 }
 function restore(r){if(motions.some(m=>m.r===r))return false;r.hp=r.maxHp;changeParts(r,new T.Matrix4());for(const {c,index}of r.colliders){c.removed=false;const guide=byName.get('Colliders_AABB');if(guide&&index<guide.count){const o=new T.Object3D();o.position.set(c.x,c.y,c.z);o.scale.set(c.w,c.h,c.d);o.updateMatrix();guide.setMatrixAt(index,o.matrix);guide.instanceMatrix.needsUpdate=true}}r.stump?.removeFromParent();r.stump=null;persist();window.dispatchEvent(new Event('world-physics-changed'));return true}
 const api={strike,update,restore,inventory,resources,save:persist,getTarget:()=>target,damage:1};return api;
}
